import { useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import {
  ArrowLeft, ArrowUpRight, Bath, BedDouble, Bell, Building2, CalendarDays, Check,
  ChevronDown, CircleDollarSign, Clock3, Compass, Heart, Home as HomeIcon, LayoutDashboard,
  MapPin, Menu, Package, Phone, Plus, Ruler, Search, Send, Settings2, ShieldCheck,
  ShoppingBag, SlidersHorizontal, Sparkles, Star, Store, Tag, UserRound, UsersRound, X, Zap
} from 'lucide-react';
import {
  getGetDashboardSummaryQueryKey, getGetPropertyQueryKey, getHealthCheckQueryKey,
  getListFinishingServicesQueryKey, getListProductsQueryKey, getListProfessionalsQueryKey,
  getListPropertiesQueryKey, useCalculateFinishingQuote, useCreateAppointment, useCreateOrder,
  useCreateProperty, useCreateViewingRequest, useGetDashboardSummary, useGetProperty,
  useHealthCheck, useListFinishingServices, useListProducts, useListProfessionals,
  useListProperties, useTogglePropertyFavorite
} from '@workspace/api-client-react';
import type {
  FinishingService, Product, Professional, Property
} from '@workspace/api-client-react';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';

const queryClient = new QueryClient();
const money = (value: number) => `${new Intl.NumberFormat('ar-EG').format(value)} ج.م`;
const number = (value: number) => new Intl.NumberFormat('ar-EG').format(value);

function Shell({ children }: { children: React.ReactNode }) {
  const [open, setOpen] = useState(false);
  const [location] = useLocation();
  const links = [
    { href: '/', label: 'الرئيسية', icon: Compass },
    { href: '/properties', label: 'اكتشف العقارات', icon: Building2 },
    { href: '/finishing', label: 'التشطيب والبيت الذكي', icon: Sparkles },
    { href: '/professionals', label: 'خبراء موثوقون', icon: UsersRound },
    { href: '/marketplace', label: 'سوق البيت', icon: Store },
    { href: '/dashboard', label: 'لوحة المتابعة', icon: LayoutDashboard },
  ];
  return (
    <div dir="rtl" className="min-h-[100dvh] bg-background text-foreground makana-noise">
      <header className="sticky top-0 z-40 border-b border-border/80 bg-background/90 backdrop-blur-xl">
        <div className="mx-auto flex h-[72px] max-w-[1440px] items-center justify-between px-5 lg:px-10">
          <Link href="/" data-testid="link-logo" className="flex items-center gap-3">
            <span className="flex h-10 w-10 items-center justify-center rounded-[13px] bg-primary text-accent shadow-sm"><HomeIcon size={20} strokeWidth={2.5} /></span>
            <span className="leading-none"><strong className="display-font text-[25px] tracking-tight">مَكانا</strong><small className="mr-2 text-[10px] font-semibold tracking-[.16em] text-muted-foreground">لبيتك مكان</small></span>
          </Link>
          <nav className="hidden items-center gap-1 lg:flex">
            {links.slice(0, 5).map(({ href, label }) => <Link key={href} href={href} data-testid={`link-nav-${href.slice(1) || 'home'}`} className={`rounded-lg px-3 py-2 text-sm font-semibold ${location === href ? 'bg-secondary text-primary' : 'text-muted-foreground hover:bg-secondary hover:text-foreground'}`}>{label}</Link>)}
          </nav>
          <div className="flex items-center gap-2">
            <Link href="/dashboard" data-testid="link-account" className="hidden items-center gap-2 rounded-lg px-3 py-2 text-sm font-semibold text-muted-foreground hover:bg-secondary hover:text-foreground sm:flex"><UserRound size={17} /> حسابي</Link>
            <button type="button" data-testid="button-mobile-menu" aria-label="فتح القائمة" className="button-ghost p-2 lg:hidden" onClick={() => setOpen(!open)}>{open ? <X size={18} /> : <Menu size={18} />}</button>
          </div>
        </div>
        {open && <div className="border-t border-border bg-card px-5 py-3 lg:hidden">{links.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-mobile-${href.slice(1) || 'home'}`} className="flex items-center gap-3 border-b border-border/70 py-3 text-sm font-semibold last:border-0"><Icon size={17} className="text-primary" />{label}</Link>)}</div>}
      </header>
      <main>{children}</main>
      <footer className="mt-24 border-t border-border bg-primary px-5 py-10 text-primary-foreground lg:px-10">
        <div className="mx-auto flex max-w-[1440px] flex-col justify-between gap-8 md:flex-row">
          <div><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-accent text-accent-foreground"><HomeIcon size={17} /></span><strong className="display-font text-2xl">مَكانا</strong></div><p className="mt-3 max-w-xs text-sm leading-7 text-primary-foreground/65">كل ما يحتاجه بيتك، من أول مفتاح الباب لآخر لمسة فيه.</p></div>
          <div className="flex gap-14 text-sm"><div><p className="mb-3 font-bold text-accent">استكشف</p><Link href="/properties" className="block py-1 text-primary-foreground/70 hover:text-accent">العقارات</Link><Link href="/professionals" className="block py-1 text-primary-foreground/70 hover:text-accent">الخبراء</Link></div><div><p className="mb-3 font-bold text-accent">ساعدنا نساعدك</p><p className="py-1 text-primary-foreground/70">أهلًا بك في مكانك</p><p className="py-1 text-primary-foreground/70">مركز الدعم</p></div></div>
        </div>
      </footer>
    </div>
  );
}

function Loading({ label = 'نجهز لك التفاصيل...' }: { label?: string }) {
  return <div className="mx-auto flex max-w-6xl flex-col items-center justify-center py-24 text-center"><div className="mb-5 flex gap-1.5"><i className="h-2 w-2 animate-pulse rounded-full bg-accent" /><i className="h-2 w-2 animate-pulse rounded-full bg-primary [animation-delay:120ms]" /><i className="h-2 w-2 animate-pulse rounded-full bg-accent [animation-delay:240ms]" /></div><p className="text-sm text-muted-foreground">{label}</p></div>;
}
function ErrorState({ retry }: { retry?: () => void }) {
  return <div className="mx-auto flex max-w-lg flex-col items-center justify-center py-20 text-center"><span className="mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-destructive/10 text-destructive"><Zap size={23} /></span><h3 className="text-lg font-bold">حصلت مشكلة بسيطة</h3><p className="mt-2 text-sm text-muted-foreground">ممكن تعيد المحاولة؟ نحن نراجع الاتصال الآن.</p>{retry && <button data-testid="button-retry" onClick={retry} className="button-primary mt-5">إعادة المحاولة</button>}</div>;
}
function EmptyState({ title, body }: { title: string; body: string }) {
  return <div className="rounded-2xl border border-dashed border-border bg-card/60 px-6 py-16 text-center"><span className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-secondary text-primary"><Compass size={21} /></span><h3 className="mt-4 text-lg font-bold">{title}</h3><p className="mt-2 text-sm text-muted-foreground">{body}</p></div>;
}
function SectionHeading({ eyebrow, title, body, action }: { eyebrow?: string; title: string; body?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-xs font-bold tracking-[.12em] text-accent">{eyebrow}</p>}<h2 className="display-font text-3xl font-extrabold tracking-tight text-primary md:text-4xl">{title}</h2>{body && <p className="mt-2 max-w-xl text-sm leading-7 text-muted-foreground">{body}</p>}</div>{action}</div>;
}
function PropertyCard({ item, onFavorite }: { item: Property; onFavorite?: (id: number) => void }) {
  return <article data-testid={`card-property-${item.id}`} className="group overflow-hidden rounded-2xl border border-border bg-card shadow-[0_8px_30px_rgba(31,71,83,.06)] transition-transform hover:-translate-y-1">
    <div className="relative h-52 overflow-hidden bg-secondary"><img src={item.image} alt={item.title} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /><div className="absolute right-3 top-3 flex gap-2"><span className="rounded-full bg-card/90 px-3 py-1 text-xs font-bold text-primary backdrop-blur">{item.listingType === 'sale' ? 'للبيع' : 'للإيجار'}</span>{item.featured && <span className="rounded-full bg-accent px-3 py-1 text-xs font-bold text-accent-foreground">مختار لك</span>}</div>{onFavorite && <button type="button" data-testid={`button-favorite-${item.id}`} onClick={() => onFavorite(item.id)} aria-label="حفظ العقار" className="absolute left-3 top-3 flex h-9 w-9 items-center justify-center rounded-full bg-card/90 text-primary backdrop-blur hover:bg-accent"><Heart size={17} /></button>}</div>
    <div className="p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-xs text-muted-foreground">{item.propertyType} · {item.finish}</p><h3 className="mt-1 line-clamp-1 font-bold text-primary">{item.title}</h3></div><p data-testid={`text-price-${item.id}`} className="whitespace-nowrap text-sm font-extrabold text-primary">{money(item.price)}</p></div><p className="mt-2 flex items-center gap-1 text-xs text-muted-foreground"><MapPin size={13} className="text-accent" />{item.district}، {item.governorate}</p><div className="mt-4 flex items-center gap-4 border-t border-border pt-3 text-xs text-muted-foreground"><span className="flex items-center gap-1"><Ruler size={14} />{number(item.area)}م²</span><span className="flex items-center gap-1"><BedDouble size={14} />{number(item.rooms)} غرف</span><span className="flex items-center gap-1"><Bath size={14} />{number(item.bathrooms)}</span><Link href={`/properties/${item.id}`} data-testid={`link-property-${item.id}`} className="mr-auto text-primary hover:text-accent"><ArrowLeft size={17} /></Link></div></div>
  </article>;
}

function Home() {
  const featured = useListProperties({ featured: true });
  const health = useHealthCheck({ query: { queryKey: getHealthCheckQueryKey(), retry: false } });
  const items = (featured.data ?? []).slice(0, 3);
  return <div>
    <section className="makana-grid relative overflow-hidden border-b border-border"><div className="mx-auto grid max-w-[1440px] items-center gap-12 px-5 py-16 md:py-24 lg:grid-cols-[1.05fr_.95fr] lg:px-10"><div className="animate-rise-in"><div className="mb-5 inline-flex items-center gap-2 rounded-full border border-accent/40 bg-accent/10 px-3 py-1.5 text-xs font-bold text-primary"><ShieldCheck size={15} className="text-accent" /> مكان موثوق لكل خطوة</div><h1 className="display-font max-w-2xl text-5xl font-extrabold leading-[1.13] tracking-[-.04em] text-primary md:text-7xl">بيتك يبدأ من<br /><span className="text-accent">مَكانا.</span></h1><p className="mt-6 max-w-xl text-base leading-8 text-muted-foreground md:text-lg">نساعدك تلاقي البيت المناسب، وتكمّله على ذوقك، وتوصل لأشخاص تعرف إنك تقدر تعتمد عليهم.</p><div className="mt-8 flex flex-wrap gap-3"><Link href="/properties" data-testid="link-hero-properties" className="button-primary">اكتشف العقارات <ArrowLeft size={17} /></Link><Link href="/finishing" data-testid="link-hero-finishing" className="button-ghost">احسب تكلفة التشطيب</Link></div><div className="mt-9 flex items-center gap-3 text-xs text-muted-foreground"><span className={`h-2 w-2 rounded-full ${health.isError ? 'bg-destructive' : 'bg-emerald-500'}`} />{health.isError ? 'نعود إليك قريبًا' : 'نحن نعمل بكامل طاقتنا'} <span className="text-border">|</span> آلاف البيوت تبدأ هنا</div></div><div className="relative hidden min-h-[390px] lg:block"><div className="absolute inset-10 rounded-[40px] bg-primary/10 rotate-3" /><div className="absolute inset-0 overflow-hidden rounded-[36px] bg-primary">{items[0]?.image ? <img src={items[0].image} alt="بيت دافئ" className="h-full w-full object-cover opacity-90" /> : <div className="makana-grid h-full w-full bg-primary/90" />}<div className="absolute inset-x-5 bottom-5 flex items-end justify-between rounded-2xl border border-white/20 bg-primary/75 p-4 text-primary-foreground backdrop-blur"><div><p className="text-xs text-primary-foreground/65">الاختيار الأقرب لقلبك</p><p className="mt-1 font-bold">{items[0]?.title || 'بيت يشبهك أكثر'}</p></div><ArrowUpRight size={22} className="text-accent" /></div></div><div className="animate-float-soft absolute -right-7 top-12 rounded-2xl border border-border bg-card p-4 shadow-lg"><div className="flex items-center gap-2 text-xs font-bold text-primary"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-accent/20 text-accent"><Check size={15} /></span>اختيارات مدروسة</div></div></div></div></section>
    <section className="mx-auto max-w-[1440px] px-5 py-16 lg:px-10"><SectionHeading eyebrow="تصفح براحة" title="نبدأ من المكان الذي يناسبك" body="اختر الخطوة الأقرب لك، وسنترك التفاصيل علينا." /><div className="grid gap-4 md:grid-cols-3"><Link href="/properties" data-testid="card-action-properties" className="group relative overflow-hidden rounded-2xl bg-primary p-6 text-primary-foreground md:col-span-2"><Building2 className="mb-16 text-accent" size={29} /><h3 className="text-2xl font-bold">بيت جديد، بداية جديدة</h3><p className="mt-2 max-w-md text-sm leading-6 text-primary-foreground/70">عقارات منتقاة من القاهرة إلى الساحل، مع المعلومات التي تهمك فعلًا.</p><ArrowLeft className="absolute bottom-6 left-6 transition-transform group-hover:-translate-x-1" /></Link><Link href="/finishing" data-testid="card-action-finishing" className="group rounded-2xl border border-border bg-secondary p-6"><Sparkles className="mb-16 text-primary" size={29} /><h3 className="text-xl font-bold text-primary">خليه على ذوقك</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">تشطيب وبيت ذكي، بأسعار واضحة من البداية.</p><ArrowLeft className="mt-5 text-primary transition-transform group-hover:-translate-x-1" /></Link><Link href="/professionals" data-testid="card-action-professionals" className="group rounded-2xl border border-border bg-card p-6"><UsersRound className="mb-8 text-accent" size={29} /><h3 className="text-xl font-bold text-primary">ناس تعرف شغلها</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">خبراء ومهنيون نثق فيهم لمشوار بيتك القادم.</p><ArrowLeft className="mt-5 text-primary transition-transform group-hover:-translate-x-1" /></Link><Link href="/marketplace" data-testid="card-action-marketplace" className="group rounded-2xl border border-border bg-card p-6 md:col-span-2"><ShoppingBag className="mb-8 text-accent" size={29} /><div className="flex items-end justify-between"><div><h3 className="text-xl font-bold text-primary">تفاصيل تصنع الفرق</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">منتجات مختارة تضيف للبيت معنى، لا زحامًا.</p></div><ArrowLeft className="text-primary transition-transform group-hover:-translate-x-1" /></div></Link></div></section>
    <section className="bg-secondary/60 px-5 py-16 lg:px-10"><div className="mx-auto max-w-[1440px]"><SectionHeading eyebrow="مَكانا بالأرقام" title="راحة البال لها تفاصيل" /><div className="grid grid-cols-2 gap-8 md:grid-cols-4"><div><p className="display-font text-4xl font-bold text-primary">١٢+</p><p className="mt-2 text-sm text-muted-foreground">محافظة نغطيها</p></div><div><p className="display-font text-4xl font-bold text-primary">٤.٨</p><p className="mt-2 text-sm text-muted-foreground">متوسط تقييم الخبراء</p></div><div><p className="display-font text-4xl font-bold text-primary">٢٤/٧</p><p className="mt-2 text-sm text-muted-foreground">نحن هنا عندما تحتاجنا</p></div><div><p className="display-font text-4xl font-bold text-primary">خطوة</p><p className="mt-2 text-sm text-muted-foreground">واحدة تفصل بينك وبين البداية</p></div></div></div></section>
    <section className="mx-auto max-w-[1440px] px-5 py-16 lg:px-10"><SectionHeading eyebrow="مختار لك اليوم" title="عقارات تستحق أن تراها" action={<Link href="/properties" data-testid="link-see-all-properties" className="button-ghost">كل العقارات <ArrowLeft size={16} /></Link>} />{featured.isLoading ? <Loading /> : featured.isError ? <ErrorState retry={() => featured.refetch()} /> : items.length === 0 ? <EmptyState title="نجهز اختيارات جديدة" body="عد إلينا قريبًا لتجد ما يشبهك." /> : <div className="grid gap-5 md:grid-cols-3">{items.map((item) => <PropertyCard key={item.id} item={item} />)}</div>}</section>
  </div>;
}

function PropertiesPage() {
  const [search, setSearch] = useState('');
  const [type, setType] = useState('');
  const [listing, setListing] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const params = useMemo(() => ({ search: search || undefined, propertyType: type || undefined, listingType: listing || undefined, maxPrice: maxPrice ? Number(maxPrice) : undefined }), [search, type, listing, maxPrice]);
  const query = useListProperties(params, { query: { queryKey: getListPropertiesQueryKey(params) } });
  const favorite = useTogglePropertyFavorite();
  return <div className="mx-auto max-w-[1440px] px-5 py-12 lg:px-10"><div className="mb-10 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mb-2 text-xs font-bold tracking-[.12em] text-accent">اكتشف مَكانك</p><h1 className="display-font text-4xl font-extrabold text-primary md:text-5xl">عقارات تشعر أنها لك</h1><p className="mt-3 text-sm text-muted-foreground">ابحث بهدوء، وقارن بما يهمك، وخذ أول خطوة عندما تكون مستعدًا.</p></div><span className="flex items-center gap-2 text-xs text-muted-foreground"><ShieldCheck size={16} className="text-accent" /> بيانات واضحة، بلا مفاجآت</span></div><div className="mb-8 rounded-2xl border border-border bg-card p-4 shadow-sm"><div className="grid gap-3 md:grid-cols-[1.6fr_1fr_1fr_1fr_auto]"><label><span className="field-label">ابحث عن منطقة أو عقار</span><span className="relative block"><Search size={17} className="absolute right-3 top-3 text-muted-foreground" /><input data-testid="input-property-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="مثال: التجمع، شاليه..." className="field-input pr-10" /></span></label><label><span className="field-label">نوع العقار</span><select data-testid="select-property-type" value={type} onChange={(e) => setType(e.target.value)} className="field-input"><option value="">كل الأنواع</option><option value="apartment">شقة</option><option value="villa">فيلا</option><option value="chalet">شاليه</option></select></label><label><span className="field-label">الهدف</span><select data-testid="select-listing-type" value={listing} onChange={(e) => setListing(e.target.value)} className="field-input"><option value="">بيع أو إيجار</option><option value="sale">للبيع</option><option value="rent">للإيجار</option></select></label><label><span className="field-label">حتى سعر</span><input data-testid="input-max-price" type="number" value={maxPrice} onChange={(e) => setMaxPrice(e.target.value)} placeholder="ج.م" className="field-input" /></label><button type="button" data-testid="button-filter-reset" onClick={() => { setSearch(''); setType(''); setListing(''); setMaxPrice(''); }} className="button-ghost self-end"><SlidersHorizontal size={16} /> مسح</button></div></div>{query.isLoading ? <Loading label="نبحث في الاختيارات..." /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : !query.data?.length ? <EmptyState title="لم نجد تطابقًا هذه المرة" body="جرّب توسيع البحث قليلًا أو تغيير المنطقة." /> : <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{query.data.map((item) => <PropertyCard key={item.id} item={item} onFavorite={(id) => favorite.mutate({ id })} />)}</div>}</div>;
}

function ViewingModal({ propertyId, onClose }: { propertyId: number; onClose: () => void }) {
  const create = useCreateViewingRequest();
  const [done, setDone] = useState(false);
  const submit = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); create.mutate({ data: { propertyId, name: String(f.get('name')), phone: String(f.get('phone')), preferredDate: String(f.get('date')), preferredTime: String(f.get('time')), notes: String(f.get('notes') || '') } }, { onSuccess: () => setDone(true) }); };
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-primary/45 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-2xl border border-border bg-card p-6 shadow-2xl">{done ? <div className="py-8 text-center"><span className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-emerald-100 text-emerald-700"><Check /></span><h2 className="mt-4 text-xl font-bold text-primary">وصل طلبك</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">سنتواصل معك لتأكيد المعاينة في الوقت المناسب.</p><button data-testid="button-close-success" onClick={onClose} className="button-primary mt-6">تمام</button></div> : <><div className="flex items-start justify-between"><div><p className="text-xs font-bold text-accent">خطوة بسيطة</p><h2 className="mt-1 text-xl font-bold text-primary">احجز معاينة</h2></div><button data-testid="button-close-viewing" onClick={onClose} className="button-ghost p-2"><X size={17} /></button></div><form onSubmit={submit} className="mt-6 space-y-4"><label><span className="field-label">الاسم</span><input required name="name" data-testid="input-viewing-name" className="field-input" /></label><label><span className="field-label">رقم الهاتف</span><input required name="phone" data-testid="input-viewing-phone" className="field-input" /></label><div className="grid grid-cols-2 gap-3"><label><span className="field-label">اليوم</span><input required type="date" name="date" data-testid="input-viewing-date" className="field-input" /></label><label><span className="field-label">الوقت</span><input required type="time" name="time" data-testid="input-viewing-time" className="field-input" /></label></div><label><span className="field-label">ملاحظة (اختياري)</span><textarea name="notes" data-testid="input-viewing-notes" className="field-input min-h-20 resize-none" /></label>{create.isError && <p className="text-xs text-destructive">تعذر إرسال الطلب. حاول مرة أخرى.</p>}<button disabled={create.isPending} data-testid="button-submit-viewing" className="button-accent w-full">{create.isPending ? 'جارٍ الإرسال...' : 'أرسل طلب المعاينة'} <Send size={16} /></button></form></>}</div></div>;
}

function PropertyDetail() {
  const { id } = useParams<{ id: string }>(); const propertyId = Number(id); const query = useGetProperty(propertyId, { query: { queryKey: getGetPropertyQueryKey(propertyId) } }); const [modal, setModal] = useState(false); const favorite = useTogglePropertyFavorite();
  if (query.isLoading) return <Loading />; if (query.isError || !query.data) return <ErrorState retry={() => query.refetch()} />; const item = query.data;
  return <div className="mx-auto max-w-[1440px] px-5 py-8 lg:px-10"><Link href="/properties" data-testid="link-back-properties" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary"><ArrowRightFix /> العودة للعقارات</Link><div className="grid gap-8 lg:grid-cols-[1.35fr_.65fr]"><div><div className="relative h-[360px] overflow-hidden rounded-3xl bg-secondary md:h-[520px]"><img src={item.image} alt={item.title} className="h-full w-full object-cover" /><div className="absolute bottom-5 right-5 rounded-xl bg-card/90 px-4 py-2 text-sm font-bold text-primary backdrop-blur">{item.finish}</div></div><div className="mt-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-sm text-muted-foreground">{item.propertyType} · {item.listingType === 'sale' ? 'للبيع' : 'للإيجار'}</p><h1 className="display-font mt-1 text-3xl font-extrabold text-primary md:text-4xl">{item.title}</h1><p className="mt-2 flex items-center gap-1 text-sm text-muted-foreground"><MapPin size={15} className="text-accent" />{item.district}، {item.governorate}</p></div><p className="text-2xl font-extrabold text-primary">{money(item.price)}</p></div><div className="my-7 grid grid-cols-3 gap-3 rounded-2xl bg-secondary p-4 text-center"><div><Ruler className="mx-auto mb-2 text-primary" size={19} /><p className="font-bold">{number(item.area)}م²</p><p className="text-xs text-muted-foreground">المساحة</p></div><div><BedDouble className="mx-auto mb-2 text-primary" size={19} /><p className="font-bold">{number(item.rooms)}</p><p className="text-xs text-muted-foreground">غرف</p></div><div><Bath className="mx-auto mb-2 text-primary" size={19} /><p className="font-bold">{number(item.bathrooms)}</p><p className="text-xs text-muted-foreground">حمام</p></div></div><h2 className="text-lg font-bold text-primary">عن المكان</h2><p className="mt-3 max-w-2xl text-sm leading-8 text-muted-foreground">{item.description || 'مساحة مصممة لتمنح يومك إيقاعًا أهدأ، في منطقة تجمع بين القرب والخصوصية.'}</p>{item.amenities?.length ? <div className="mt-6 flex flex-wrap gap-2">{item.amenities.map((a) => <span key={a} className="rounded-full border border-border bg-card px-3 py-1.5 text-xs font-semibold text-muted-foreground">{a}</span>)}</div> : null}</div></div><aside className="h-fit rounded-2xl border border-border bg-card p-6 shadow-[0_8px_30px_rgba(31,71,83,.08)] lg:sticky lg:top-24"><div className="flex items-center gap-3 border-b border-border pb-5"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-accent/15 text-accent"><CalendarDays size={21} /></span><div><p className="font-bold text-primary">هل تريد أن تراه على الطبيعة؟</p><p className="mt-1 text-xs text-muted-foreground">ننسق لك موعدًا يناسبك.</p></div></div><button data-testid="button-request-viewing" onClick={() => setModal(true)} className="button-accent mt-6 w-full">اطلب معاينة <ArrowLeft size={17} /></button><button data-testid="button-detail-favorite" onClick={() => favorite.mutate({ id: item.id })} className="button-ghost mt-3 w-full"><Heart size={16} /> حفظ في المفضلة</button><div className="mt-6 flex items-center gap-2 text-xs leading-5 text-muted-foreground"><ShieldCheck size={16} className="shrink-0 text-accent" />فريق مَكانا معك للتأكد من كل معلومة.</div></aside></div>{modal && <ViewingModal propertyId={item.id} onClose={() => setModal(false)} />}</div>;
}
function ArrowRightFix() { return <ArrowLeft className="rotate-180" size={16} />; }

function FinishingPage() {
  const services = useListFinishingServices({ query: { queryKey: getListFinishingServicesQueryKey() } }); const quote = useCalculateFinishingQuote(); const [selected, setSelected] = useState<FinishingService | null>(null); const [area, setArea] = useState('120'); const [result, setResult] = useState<{ estimatedCost: number; disclaimer: string } | null>(null);
  const calculate = (e: React.FormEvent) => { e.preventDefault(); if (!selected) return; quote.mutate({ data: { serviceId: selected.id, area: Number(area) } }, { onSuccess: (data) => setResult(data) }); };
  return <div className="mx-auto max-w-[1440px] px-5 py-12 lg:px-10"><section className="relative overflow-hidden rounded-3xl bg-primary px-6 py-12 text-primary-foreground md:px-12 md:py-16"><div className="relative z-10 max-w-2xl"><p className="mb-3 text-xs font-bold tracking-[.12em] text-accent">من المساحة إلى الإحساس</p><h1 className="display-font text-4xl font-extrabold leading-tight md:text-6xl">خلّي بيتك<br /><span className="text-accent">يشبهك أكثر.</span></h1><p className="mt-5 max-w-lg text-sm leading-8 text-primary-foreground/70">اختر الخدمة، أدخل مساحتك، وخذ فكرة صادقة عن تكلفة العمالة قبل أن تبدأ.</p></div><div className="absolute -left-20 -top-32 h-80 w-80 rounded-full border-[50px] border-accent/20" /><Sparkles className="absolute bottom-10 left-12 text-accent/70" size={44} /></section><div className="mt-14 grid gap-10 lg:grid-cols-[1fr_380px]"><div><SectionHeading eyebrow="خدمات البيت" title="اختر ما يحتاجه بيتك" body="من اللمسة الأولى إلى التفاصيل الذكية، كل خدمة لها سعر عمل واضح." />{services.isLoading ? <Loading /> : services.isError ? <ErrorState retry={() => services.refetch()} /> : !services.data?.length ? <EmptyState title="الخدمات ستظهر قريبًا" body="نعمل على إضافة شركاء جدد." /> : <div className="grid gap-4 md:grid-cols-2">{services.data.map((service) => <button type="button" key={service.id} data-testid={`button-service-${service.id}`} onClick={() => { setSelected(service); setResult(null); }} className={`text-right rounded-2xl border p-5 transition-transform hover:-translate-y-1 ${selected?.id === service.id ? 'border-accent bg-accent/10 shadow-sm' : 'border-border bg-card'}`}><div className="flex items-start justify-between"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-secondary text-primary"><Sparkles size={18} /></span><span className="rounded-full bg-secondary px-2.5 py-1 text-[11px] font-bold text-muted-foreground">{service.category}</span></div><h3 className="mt-5 font-bold text-primary">{service.name}</h3><p className="mt-2 text-xs leading-6 text-muted-foreground">{service.description}</p><p className="mt-4 text-sm font-bold text-primary">{money(service.laborPrice)} <span className="font-normal text-muted-foreground">/ {service.unit}</span></p></button>)}</div>}</div><aside className="h-fit rounded-2xl border border-border bg-card p-6 shadow-sm lg:sticky lg:top-24"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-accent/20 text-accent"><CircleDollarSign size={20} /></span><div><h2 className="font-bold text-primary">حاسبة مبدئية</h2><p className="text-xs text-muted-foreground">تقدير العمالة فقط</p></div></div>{selected ? <form onSubmit={calculate} className="mt-6 space-y-4"><div className="rounded-xl bg-secondary p-3 text-sm font-bold text-primary">{selected.name}</div><label><span className="field-label">المساحة بالمتر</span><input required min="1" type="number" value={area} onChange={(e) => setArea(e.target.value)} data-testid="input-finishing-area" className="field-input" /></label><button disabled={quote.isPending} data-testid="button-calculate-quote" className="button-accent w-full">{quote.isPending ? 'نحسبها لك...' : 'احسب التكلفة'} <ArrowLeft size={16} /></button>{quote.isError && <p className="text-xs text-destructive">تعذر حساب السعر الآن.</p>}{result && <div className="animate-rise-in rounded-xl border border-accent/40 bg-accent/10 p-4"><p className="text-xs text-muted-foreground">التكلفة التقديرية</p><p data-testid="text-quote-cost" className="mt-1 text-2xl font-extrabold text-primary">{money(result.estimatedCost)}</p><p className="mt-2 text-[11px] leading-5 text-muted-foreground">{result.disclaimer}</p></div>}</form> : <div className="mt-6 rounded-xl bg-secondary p-5 text-center"><p className="text-sm font-bold text-primary">ابدأ باختيار خدمة</p><p className="mt-2 text-xs leading-6 text-muted-foreground">سنحسب لك تكلفة العمالة بناءً على مساحتك.</p></div>}</aside></div></div>;
}

function ProfessionalsPage() {
  const [search, setSearch] = useState(''); const [category, setCategory] = useState(''); const params = useMemo(() => ({ search: search || undefined, category: category || undefined }), [search, category]); const query = useListProfessionals(params, { query: { queryKey: getListProfessionalsQueryKey(params) } }); const [selected, setSelected] = useState<Professional | null>(null);
  return <div className="mx-auto max-w-[1440px] px-5 py-12 lg:px-10"><SectionHeading eyebrow="ناس نثق فيهم" title="خبراء يجعلون الطريق أسهل" body="اختيارات من أشخاص حقيقيين، بخبرة يمكن أن تلمسها في كل تفصيلة." /><div className="mb-8 grid gap-3 rounded-2xl border border-border bg-card p-4 md:grid-cols-[1fr_260px]"><label><span className="field-label">ابحث باسم أو تخصص</span><span className="relative block"><Search size={17} className="absolute right-3 top-3 text-muted-foreground" /><input data-testid="input-professional-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="مهندس، نجار، تصميم..." className="field-input pr-10" /></span></label><label><span className="field-label">التخصص</span><select data-testid="select-professional-category" value={category} onChange={(e) => setCategory(e.target.value)} className="field-input"><option value="">كل التخصصات</option><option value="finishing">تشطيب</option><option value="design">تصميم داخلي</option><option value="smart-home">بيت ذكي</option></select></label></div>{query.isLoading ? <Loading /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : !query.data?.length ? <EmptyState title="لم نجد خبيرًا بهذا البحث" body="جرّب كلمة أخرى أو اترك الفلتر مفتوحًا." /> : <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{query.data.map((p) => <article key={p.id} data-testid={`card-professional-${p.id}`} className="overflow-hidden rounded-2xl border border-border bg-card p-5"><div className="flex gap-4"><div className="h-16 w-16 shrink-0 overflow-hidden rounded-2xl bg-secondary">{p.image ? <img src={p.image} alt={p.name} className="h-full w-full object-cover" /> : <span className="flex h-full items-center justify-center text-lg font-bold text-primary">{p.name.slice(0, 1)}</span>}</div><div className="min-w-0"><div className="flex items-center gap-1 text-xs text-accent"><Star size={13} fill="currentColor" />{p.rating.toFixed(1)} <span className="text-muted-foreground">· {p.experience} سنوات خبرة</span></div><h3 className="mt-1 truncate font-bold text-primary">{p.name}</h3><p className="text-xs text-muted-foreground">{p.title} · {p.specialty}</p></div></div><p className="mt-4 line-clamp-2 text-sm leading-6 text-muted-foreground">{p.bio || 'متخصص يهتم بالتفاصيل ويحوّل احتياجك إلى نتيجة تفتخر بها.'}</p><div className="mt-4 flex items-center justify-between border-t border-border pt-4"><span className={`flex items-center gap-1 text-xs font-semibold ${p.available ? 'text-emerald-700' : 'text-muted-foreground'}`}><span className={`h-2 w-2 rounded-full ${p.available ? 'bg-emerald-500' : 'bg-muted-foreground'}`} />{p.available ? 'متاح للحجز' : 'غير متاح الآن'}</span><button type="button" disabled={!p.available} data-testid={`button-appointment-${p.id}`} onClick={() => setSelected(p)} className="button-primary px-3 py-2 text-xs">احجز موعدًا</button></div></article>)}</div>}{selected && <AppointmentModal professional={selected} onClose={() => setSelected(null)} />}</div>;
}
function AppointmentModal({ professional, onClose }: { professional: Professional; onClose: () => void }) {
  const create = useCreateAppointment(); const [done, setDone] = useState(false); const submit = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); create.mutate({ data: { professionalId: professional.id, name: String(f.get('name')), phone: String(f.get('phone')), date: String(f.get('date')), time: String(f.get('time')), notes: String(f.get('notes') || '') } }, { onSuccess: () => setDone(true) }); };
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-primary/45 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-2xl bg-card p-6 shadow-2xl">{done ? <div className="py-8 text-center"><Check className="mx-auto text-emerald-600" size={42} /><h2 className="mt-4 text-xl font-bold">تم تسجيل الموعد</h2><button onClick={onClose} data-testid="button-close-appointment-success" className="button-primary mt-6">إغلاق</button></div> : <><div className="flex justify-between"><div><p className="text-xs text-accent">موعد مع</p><h2 className="mt-1 text-xl font-bold text-primary">{professional.name}</h2></div><button onClick={onClose} data-testid="button-close-appointment" className="button-ghost p-2"><X size={17} /></button></div><form onSubmit={submit} className="mt-5 space-y-3"><input required name="name" placeholder="الاسم" data-testid="input-appointment-name" className="field-input" /><input required name="phone" placeholder="رقم الهاتف" data-testid="input-appointment-phone" className="field-input" /><div className="grid grid-cols-2 gap-3"><input required type="date" name="date" data-testid="input-appointment-date" className="field-input" /><input required type="time" name="time" data-testid="input-appointment-time" className="field-input" /></div><textarea name="notes" placeholder="ما الذي تحتاجه؟" data-testid="input-appointment-notes" className="field-input min-h-20 resize-none" /><button disabled={create.isPending} data-testid="button-submit-appointment" className="button-accent w-full">{create.isPending ? 'جارٍ الحجز...' : 'تأكيد الموعد'}</button></form></>}</div></div>;
}

function MarketplacePage() {
  const [category, setCategory] = useState(''); const [search, setSearch] = useState(''); const params = useMemo(() => ({ category: category || undefined, search: search || undefined }), [category, search]); const query = useListProducts(params, { query: { queryKey: getListProductsQueryKey(params) } }); const [cart, setCart] = useState<Record<number, number>>({}); const [checkout, setCheckout] = useState(false);
  const add = (id: number) => setCart((c) => ({ ...c, [id]: (c[id] || 0) + 1 })); const count = Object.values(cart).reduce((a, b) => a + b, 0); const products = query.data ?? [];
  return <div className="mx-auto max-w-[1440px] px-5 py-12 lg:px-10"><div className="mb-9 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mb-2 text-xs font-bold tracking-[.12em] text-accent">سوق البيت</p><h1 className="display-font text-4xl font-extrabold text-primary md:text-5xl">تفاصيل صغيرة، فرق كبير</h1><p className="mt-3 text-sm text-muted-foreground">أشياء نختارها كما لو كانت لبيتنا.</p></div><button type="button" onClick={() => setCheckout(true)} data-testid="button-open-cart" className="button-primary"><ShoppingBag size={17} /> السلة <span className="rounded-full bg-accent px-2 py-0.5 text-xs text-accent-foreground">{count}</span></button></div><div className="mb-8 flex flex-col gap-3 sm:flex-row"><span className="relative flex-1"><Search size={17} className="absolute right-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} data-testid="input-product-search" placeholder="ابحث في المنتجات..." className="field-input pr-10" /></span><select value={category} onChange={(e) => setCategory(e.target.value)} data-testid="select-product-category" className="field-input sm:w-56"><option value="">كل الفئات</option><option value="lighting">إضاءة</option><option value="decor">ديكور</option><option value="smart-home">بيت ذكي</option></select></div>{query.isLoading ? <Loading /> : query.isError ? <ErrorState retry={() => query.refetch()} /> : !products.length ? <EmptyState title="لا توجد منتجات الآن" body="نضيف اختيارات جديدة بعناية، عد إلينا قريبًا." /> : <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{products.map((p) => <ProductCard key={p.id} product={p} onAdd={() => add(p.id)} />)}</div>}{checkout && <CartModal products={products} cart={cart} onClose={() => setCheckout(false)} onClear={() => setCart({})} />}</div>;
}
function ProductCard({ product, onAdd }: { product: Product; onAdd: () => void }) {
  return <article data-testid={`card-product-${product.id}`} className="group overflow-hidden rounded-2xl border border-border bg-card"><div className="relative h-48 bg-secondary"><img src={product.image} alt={product.name} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" />{product.badge && <span className="absolute right-3 top-3 rounded-full bg-accent px-2.5 py-1 text-[11px] font-bold text-accent-foreground">{product.badge}</span>}</div><div className="p-4"><p className="text-xs text-muted-foreground">{product.vendor} · {product.category}</p><h3 className="mt-1 font-bold text-primary">{product.name}</h3>{product.description && <p className="mt-2 line-clamp-2 text-xs leading-5 text-muted-foreground">{product.description}</p>}<div className="mt-4 flex items-center justify-between"><div><p className="font-extrabold text-primary">{money(product.price)}</p>{product.oldPrice > product.price && <p className="text-xs text-muted-foreground line-through">{money(product.oldPrice)}</p>}</div><button type="button" disabled={!product.stock} onClick={onAdd} data-testid={`button-add-product-${product.id}`} className="button-accent px-3 py-2 text-xs">{product.stock ? <><Plus size={15} /> أضف</> : 'نفد'}</button></div></div></article>;
}
function CartModal({ products, cart, onClose, onClear }: { products: Product[]; cart: Record<number, number>; onClose: () => void; onClear: () => void }) {
  const order = useCreateOrder(); const [done, setDone] = useState(false); const entries = products.filter((p) => cart[p.id]); const total = entries.reduce((a, p) => a + p.price * (cart[p.id] || 0), 0); const submit = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); order.mutate({ data: { name: String(f.get('name')), phone: String(f.get('phone')), address: String(f.get('address')), items: entries.map((p) => ({ productId: p.id, quantity: cart[p.id] })) } }, { onSuccess: () => { setDone(true); onClear(); } }); };
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-primary/45 p-4 backdrop-blur-sm"><div className="w-full max-w-lg rounded-2xl bg-card p-6 shadow-2xl">{done ? <div className="py-10 text-center"><Check className="mx-auto text-emerald-600" size={42} /><h2 className="mt-4 text-xl font-bold">طلبك في الطريق</h2><p className="mt-2 text-sm text-muted-foreground">سنتواصل معك لتأكيد التفاصيل.</p><button onClick={onClose} data-testid="button-close-order-success" className="button-primary mt-6">إغلاق</button></div> : <><div className="flex items-start justify-between"><div><p className="text-xs font-bold text-accent">سلتك</p><h2 className="mt-1 text-xl font-bold text-primary">{entries.length ? `${number(Object.keys(cart).length)} اختيارات` : 'السلة فارغة'}</h2></div><button onClick={onClose} data-testid="button-close-cart" className="button-ghost p-2"><X size={17} /></button></div>{entries.length ? <><div className="my-5 space-y-3">{entries.map((p) => <div key={p.id} className="flex items-center justify-between rounded-xl bg-secondary p-3 text-sm"><span className="font-semibold">{p.name} × {cart[p.id]}</span><b>{money(p.price * cart[p.id])}</b></div>)}</div><p className="flex justify-between border-t border-border pt-4 font-bold text-primary"><span>الإجمالي</span><span>{money(total)}</span></p><form onSubmit={submit} className="mt-5 space-y-3"><input required name="name" placeholder="الاسم" data-testid="input-order-name" className="field-input" /><input required name="phone" placeholder="رقم الهاتف" data-testid="input-order-phone" className="field-input" /><input required name="address" placeholder="العنوان بالتفصيل" data-testid="input-order-address" className="field-input" /><button disabled={order.isPending} data-testid="button-submit-order" className="button-accent w-full">{order.isPending ? 'جارٍ تأكيد الطلب...' : 'تأكيد الطلب'} <Send size={15} /></button></form></> : <div className="py-10 text-center text-sm text-muted-foreground">أضف قطعة تحبها لتظهر هنا.</div>}</>}</div></div>;
}

function PropertySubmitModal({ onClose }: { onClose: () => void }) {
  const create = useCreateProperty(); const queryClient = useQueryClient(); const [done, setDone] = useState(false);
  const submit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault(); const f = new FormData(e.currentTarget);
    create.mutate({ data: { title: String(f.get('title')), propertyType: String(f.get('propertyType')), listingType: String(f.get('listingType')), price: Number(f.get('price')), area: Number(f.get('area')), rooms: Number(f.get('rooms')), bathrooms: Number(f.get('bathrooms')), governorate: String(f.get('governorate')), district: String(f.get('district')), finish: String(f.get('finish')), image: String(f.get('image')), description: String(f.get('description') || '') } }, {
      onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListPropertiesQueryKey() }); setDone(true); },
    });
  };
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-primary/45 p-4 backdrop-blur-sm"><div className="max-h-[90dvh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-card p-6 shadow-2xl">{done ? <div className="py-10 text-center"><Check className="mx-auto text-emerald-600" size={42} /><h2 className="mt-4 text-xl font-bold text-primary">تم إرسال العقار للمراجعة</h2><p className="mt-2 text-sm text-muted-foreground">سنراجعه ونعود إليك عند نشره.</p><button onClick={onClose} data-testid="button-close-property-success" className="button-primary mt-6">إغلاق</button></div> : <><div className="flex items-start justify-between"><div><p className="text-xs font-bold text-accent">إضافة إلى مَكانا</p><h2 className="mt-1 text-xl font-bold text-primary">أضف عقارًا للمراجعة</h2></div><button onClick={onClose} data-testid="button-close-property-form" className="button-ghost p-2"><X size={17} /></button></div><form onSubmit={submit} className="mt-6 grid gap-4 sm:grid-cols-2"><label className="sm:col-span-2"><span className="field-label">اسم العقار</span><input required name="title" data-testid="input-property-title" className="field-input" /></label><label><span className="field-label">النوع</span><select name="propertyType" data-testid="select-submit-property-type" className="field-input"><option value="apartment">شقة</option><option value="villa">فيلا</option><option value="chalet">شاليه</option></select></label><label><span className="field-label">الهدف</span><select name="listingType" data-testid="select-submit-listing-type" className="field-input"><option value="sale">للبيع</option><option value="rent">للإيجار</option></select></label><label><span className="field-label">السعر</span><input required min="1" type="number" name="price" data-testid="input-submit-price" className="field-input" /></label><label><span className="field-label">المساحة</span><input required min="1" type="number" name="area" data-testid="input-submit-area" className="field-input" /></label><label><span className="field-label">الغرف</span><input required min="0" type="number" name="rooms" data-testid="input-submit-rooms" className="field-input" /></label><label><span className="field-label">الحمامات</span><input required min="0" type="number" name="bathrooms" data-testid="input-submit-bathrooms" className="field-input" /></label><label><span className="field-label">المحافظة</span><input required name="governorate" data-testid="input-submit-governorate" className="field-input" /></label><label><span className="field-label">المنطقة</span><input required name="district" data-testid="input-submit-district" className="field-input" /></label><label><span className="field-label">التشطيب</span><input required name="finish" data-testid="input-submit-finish" placeholder="تشطيب كامل" className="field-input" /></label><label><span className="field-label">رابط الصورة</span><input required type="url" name="image" data-testid="input-submit-image" className="field-input" /></label><label className="sm:col-span-2"><span className="field-label">وصف مختصر</span><textarea name="description" data-testid="input-submit-description" className="field-input min-h-20 resize-none" /></label>{create.isError && <p className="text-xs text-destructive sm:col-span-2">تعذر إرسال العقار. راجع البيانات وحاول مرة أخرى.</p>}<button disabled={create.isPending} data-testid="button-submit-property" className="button-accent sm:col-span-2">{create.isPending ? 'جارٍ الإرسال...' : 'إرسال للمراجعة'} <Send size={15} /></button></form></>}</div></div>;
}

function DashboardPage() {
  const query = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } }); const [propertyForm, setPropertyForm] = useState(false); const s = query.data;
  if (query.isLoading) return <Loading label="نرتب لوحة المتابعة..." />; if (query.isError || !s) return <ErrorState retry={() => query.refetch()} />;
  const stats = [{ label: 'المستخدمون', value: s.users, icon: UsersRound }, { label: 'العقارات المنشورة', value: s.publishedProperties ?? s.properties, icon: Building2 }, { label: 'طلبات المعاينة', value: s.viewingRequests, icon: CalendarDays }, { label: 'الطلبات', value: s.orders, icon: Package }];
  return <div className="mx-auto max-w-[1440px] px-5 py-12 lg:px-10"><div className="mb-10 flex items-end justify-between"><div><p className="mb-2 text-xs font-bold tracking-[.12em] text-accent">مساحتك في مَكانا</p><h1 className="display-font text-4xl font-extrabold text-primary">أهلًا بك من جديد</h1><p className="mt-2 text-sm text-muted-foreground">نظرة هادئة على كل ما يتحرك حول بيتك.</p></div><div className="flex gap-2"><button type="button" onClick={() => setPropertyForm(true)} data-testid="button-add-property" className="button-accent"><Plus size={16} /> إضافة عقار</button><button type="button" data-testid="button-dashboard-settings" className="button-ghost p-2 sm:px-3"><Settings2 size={16} /><span className="hidden sm:inline">الإعدادات</span></button></div></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{stats.map(({ label, value, icon: Icon }, i) => <div key={label} data-testid={`stat-${i}`} className={`rounded-2xl border border-border p-5 ${i === 0 ? 'bg-primary text-primary-foreground' : 'bg-card'}`}><div className="flex items-center justify-between"><span className={`flex h-10 w-10 items-center justify-center rounded-xl ${i === 0 ? 'bg-primary-foreground/10 text-accent' : 'bg-secondary text-primary'}`}><Icon size={19} /></span><ArrowUpRight size={16} className={i === 0 ? 'text-accent' : 'text-muted-foreground'} /></div><p className={`mt-7 text-3xl font-extrabold ${i === 0 ? '' : 'text-primary'}`}>{number(value)}</p><p className={`mt-1 text-xs ${i === 0 ? 'text-primary-foreground/65' : 'text-muted-foreground'}`}>{label}</p></div>)}</div><div className="mt-8 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><div className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><h2 className="font-bold text-primary">نبض المنصة</h2><span className="flex items-center gap-1 text-xs text-emerald-700"><span className="h-2 w-2 rounded-full bg-emerald-500" /> محدث الآن</span></div><div className="mt-7 grid gap-4 sm:grid-cols-2"><div className="rounded-xl bg-secondary p-4"><p className="text-xs text-muted-foreground">عقارات قيد المراجعة</p><p className="mt-2 text-2xl font-extrabold text-primary">{number(s.pendingProperties)}</p><div className="mt-3 h-1.5 rounded-full bg-border"><div className="h-full w-2/3 rounded-full bg-accent" /></div></div><div className="rounded-xl bg-secondary p-4"><p className="text-xs text-muted-foreground">طلبات التشطيب</p><p className="mt-2 text-2xl font-extrabold text-primary">{number(s.finishingRequests)}</p><div className="mt-3 h-1.5 rounded-full bg-border"><div className="h-full w-1/2 rounded-full bg-primary" /></div></div></div></div><div className="rounded-2xl bg-accent p-6 text-accent-foreground"><Sparkles size={24} /><h2 className="mt-7 text-xl font-extrabold">ماذا بعد؟</h2><p className="mt-2 text-sm leading-7 text-accent-foreground/75">اكتشف خبيرًا يساعدك تنقل فكرتك من الورق إلى بيت حقيقي.</p><Link href="/professionals" data-testid="link-dashboard-professionals" className="mt-5 inline-flex items-center gap-2 text-sm font-bold underline underline-offset-4">تصفح الخبراء <ArrowLeft size={15} /></Link></div></div><div className="mt-5 flex flex-wrap gap-3 text-xs text-muted-foreground"><span className="rounded-full border border-border bg-card px-3 py-2">الخبراء: {number(s.professionals)}</span><span className="rounded-full border border-border bg-card px-3 py-2">منتجات السوق: {number(s.products)}</span>{s.revenue !== undefined && <span className="rounded-full border border-border bg-card px-3 py-2">إجمالي الإيرادات: {money(s.revenue)}</span>}</div>{propertyForm && <PropertySubmitModal onClose={() => setPropertyForm(false)} />}</div>;
}

function Router() {
  return <ErrorBoundary resetKey={useLocation()[0]}><Shell><Switch><Route path="/" component={Home} /><Route path="/properties" component={PropertiesPage} /><Route path="/properties/:id" component={PropertyDetail} /><Route path="/finishing" component={FinishingPage} /><Route path="/professionals" component={ProfessionalsPage} /><Route path="/marketplace" component={MarketplacePage} /><Route path="/dashboard" component={DashboardPage} /><Route component={() => <div className="mx-auto max-w-2xl px-5 py-28 text-center"><h1 className="display-font text-5xl font-extrabold text-primary">هذه الصفحة غير موجودة</h1><Link href="/" className="button-primary mt-7">العودة للرئيسية</Link></div>} /></Switch></Shell></ErrorBoundary>;
}
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;